    69→where
    70→    L: ToTxEnv<TxEnv>,
    71→    R: ToTxEnv<TxEnv>,
    72→{
    73→    fn to_tx_env(&self) -> TxEnv {
    74→        match self {
    75→            Self::Left(l) => l.to_tx_env(),
